// tuning helper (s04tex r20): one vite + browser, several query variants, a few audit shots each (same shot method as
// tools/lead_r6/motion_audit.mjs; the shot list always runs in the same order so the sim states match between variants).
// node tune.mjs <outRoot> <baseQueryFile> <shots comma list> <name>=<extra query> ...
import { mkdirSync, readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
const { loadPlaywright, CHROMIUM_ARGS, startVite } = await import(pathToFileURL(`${process.cwd()}/scripts/lib/pw.mjs`).href);
const [OUT, QF, SH, ...VARS] = process.argv.slice(2);
const BASE = readFileSync(QF, 'utf8').trim();
const ALL = [['f03_forward3u', 3, null], ['f06_forward6u', 6, null], ['f10_forward10u', 10, null], ['f20_forward20u', 20, null],
  ['s_left_steer', 6, -1], ['s_right_steer', 6, 1], ['s_left_hard', 12, -1], ['s_right_hard', 12, 1],
  ['t66_through_screen', 't0.66', null]];
const want = SH.split(',');
const SHOTS = ALL.filter((s) => want.includes(s[0]));
const { chromium } = loadPlaywright();
const vite = await startVite(5274);
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
try {
  for (const v of VARS) {
    const i = v.indexOf('=');
    const name = v.slice(0, i), extra = v.slice(i + 1);
    const out = `${OUT}/${name}`; mkdirSync(out, { recursive: true });
    const page = await browser.newPage({ viewport: { width: 864, height: 1536 }, deviceScaleFactor: 1 });
    page.on('pageerror', (e) => console.error('pageerror', e.message));
    page.on('console', (m) => { if (m.type() === 'error' && !/font|woff/i.test(m.text())) console.error('console', m.text().slice(0, 300)); });
    await page.goto(`${vite.url}/?qa=1&dpr=1&${BASE}${extra ? '&' + extra : ''}`);
    await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 300000 });
    for (const [sn, dist, steer] of SHOTS) {
      const st = await page.evaluate(async ([id, dist, steer]) => {
        const r = window.__rainbow; r.goto(id);
        const s0 = r.state().s;
        const stg = r.course.stage(id);
        const s1 = stg.s1 ?? (stg.s0 + (stg.length ?? 0));
        const target = typeof dist === 'string' ? s0 + Number(dist.slice(1)) * Math.max(0, s1 - s0) : s0 + dist;
        r.setSteer(steer);
        let n = 0; while (r.state().s < target - 1e-3 && n < 4000) { r.step(1); n++; }
        r.setSteer(null);
        r.run(true); await new Promise((res) => requestAnimationFrame(() => requestAnimationFrame(res))); r.run(false);
        return { ...r.state(), frames: n };
      }, ['04', dist, steer]);
      await page.waitForTimeout(150);
      await page.screenshot({ path: `${out}/${sn}.png` });
      console.log(name, sn, 's', st.s.toFixed(3), 'lat', st.lat, 'coins', st.coins);
    }
    await page.close();
  }
} finally {
  await browser.close(); await vite.close?.();
}

