        fd *= step(0.999, vF.y);                                     // corridor rings only (the telescope stays painted)
#endif
        if (fd > 0.001) {
          float lastS = step(Ns - 0.5, si);                          // the last sub-band ends at the modelled lip
          float sid = kI * 7.0 + si;                                 // world-anchored id of this sub-band
          // (a) a rounded polished tube: dark just after its groove, a broad lit crown, rolling off into its rim
          float crown = smoothstep(0.0, 0.5, xs) * (1.0 - 0.6 * smoothstep(0.8, 1.0, xs) * (1.0 - lastS));
          pr *= 1.0 + uRNear2.x * fd * (crown - 0.55);
          // (b) the washer rim's yellow-gold: warm (copper) texels shift a little toward gold; pink / violet texels stay
          float warm = smoothstep(0.04, 0.22, pr.r - pr.b);
          pr.g *= 1.0 + 0.12 * uRNear2.z * fd * warm;
          pr.b *= 1.0 - 0.06 * uRNear2.z * fd * warm;
          // (c) polished highlights that move: the tube normal tilts from facing the viewer (after the groove) to facing down
          // the tunnel (at the rim); where it mirrors the bright end there is a highlight, gathered into a few hot spots
          // round the ring (world-anchored per sub-band, like the painted light columns), with a sharp warm-white core
          float th = (xs - 0.5) * 1.5;
          vec3 nT = normalize(n * cos(th) + uAxD * sin(th));
